class Solution {
public:
    string encode(string s) {
        int n = static_cast<int>(s.size());
        if (n == 0) {
            return "";
        }
        vector<vector<string>> dp(n, vector<string>(n));
        for (int length = 1; length <= n; ++length) {
            for (int left = 0; left + length <= n; ++left) {
                int right = left + length - 1;
                string part = s.substr(left, length);
                dp[left][right] = part;
                for (int split = left; split < right; ++split) {
                    string candidate = dp[left][split] + dp[split + 1][right];
                    if (candidate.size() < dp[left][right].size()) {
                        dp[left][right] = candidate;
                    }
                }
                for (int unit = 1; unit <= length / 2; ++unit) {
                    if (length % unit != 0) {
                        continue;
                    }
                    bool repeated = true;
                    for (int k = unit; k < length; ++k) {
                        if (part[k] != part[k % unit]) {
                            repeated = false;
                            break;
                        }
                    }
                    if (repeated) {
                        string candidate = to_string(length / unit) + "["
                                         + dp[left][left + unit - 1] + "]";
                        if (candidate.size() < dp[left][right].size()) {
                            dp[left][right] = candidate;
                        }
                    }
                }
            }
        }
        return dp[0][n - 1];
    }
};
